INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حصن:ibn_durayd_jamharat_lugha', 'حصن', 'dadc63a651b9309ae1e2035f38', 'واشتقاقه من حصنت الشَّيْء تحصينا إِذا منعته وحظرته', 'from guarding a thing and fencing it off', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_d48e1a0c0dd0251a', '507', NULL, 'blk_jam_49cb35f814051ae5', 0, NULL, 'Marker: first gloss of this root («اشتقاقه من»). Reading: guarding.', 'high', 'active');
