INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حكم:qamus_muhit', 'حكم', '06d23d1637d1e2fc08fe45af75', 'الحُكْمُ، بالضم: القَضا', 'judging', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_242882bac906ae4c', NULL, NULL, 'blk_qms_a5388ca44a514a88', 0, NULL, 'Marker: Qāmūs gloss. Reading: judging. Differs from the main reading (holding back).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حكم:zabidi_taj_arus', 'حكم', '06d23d1637d1e2fc08fe45af75', '(الحُكْمُ، بالضَّمِّ: القَضاءُ) فِي الشَّيْء بأنّه كَذا أَو لَيْس بِكَذا', 'judging that a thing is so or not so', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_ea4761ac017c46f6', '510', 31, 'blk_taj_1b74c68f5d0166f1', 0, NULL, 'Marker: Qāmūs gloss. Reading: judging. Differs from the main reading (holding back).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حكم:lane_lexicon', 'حكم', '06d23d1637d1e2fc08fe45af75', 'in its primary acceptation, (Mṣb,) He prevented, restrained, or withheld, him (Ṣ, Mṣb, Ḳ) from acting in an evil, or a corrupt, manner', 'he held him back from doing wrong', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_08b37de3813afac8', '616', NULL, 'blk_lane_e59eb7843a5a35a3', 0, NULL, 'Marker: primary signification. Reading: holding back.', 'high', 'active');
