INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حلف:raghib_mufradat', 'حلف', 'dc9bbcd3d57409126f9e3b759c', 'والحَلِفُ أصله اليمين الذي يأخذ بعضهم من بعض بها العهد، ثمّ عبّر به عن كلّ يمين', 'an oath sealing a pact; then any oath', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_e1b50bb45eb5600b', '252', 1, 'blk_mfr_df85dc6e2de66599', 0, NULL, 'Marker: «أصله». Reading: oath for a pact.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حلف:ibn_manzur_lisan_arab', 'حلف', 'dc9bbcd3d57409126f9e3b759c', 'الحِلْفُ والحَلِفُ: القَسَمُ لُغَتَانِ، حَلَفَ أَي أَقْسَم', 'an oath; he swore', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_d39f7b91ed2946c4', '4360', 9, 'blk_lsn_15db793c15c72ff2', 0, NULL, 'Marker: head gloss. Reading: oath.', 'high', 'active');
