INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حلف:zabidi_taj_arus', 'حلف', 'dc9bbcd3d57409126f9e3b759c', 'أَي: أَحْلِفُ مَحْلُوفَةً، أَي: قَسَماً، فالمَحْلُوفَةُ: هِيَ القَسَمُ.', 'I swear an oath; maḥlūfa is the oath', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_2f32e736f4734077', '158', 23, 'blk_taj_68041a4b58f3367e', 0, NULL, 'Marker: first gloss (the opening block gives forms only). Reading: oath. Quoted from al-Layth via Tāj.', 'medium', 'active');
