INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حير:khalil_kitab_ayn', 'حير', 'cc748d32be2b7b6f69964558d0', 'حار بَصَرُهُ يَحارُ حَيْرَةً وحَيِراً، وذلك إذا نظرتَ إلى الشيءِ فَغَشِيَ بَصَرُك', 'eyes dazzled when you look at a thing', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_61874feedbb99041', '987', NULL, 'blk_kay_ecd1ea206808fd80', 0, NULL, 'Marker: «يقال … إذا». Reading: dazzled sight. Primary: dazzled sight — 4 of 8 books (al-Khalīl blk_kay_ecd1ea206808fd80; Lisān blk_lsn_88b679e2f0bc523b; Tāj blk_taj_298eb99dee62607a; Lane blk_lane_93094448343ec72c). Other readings: at a loss, wavering: al-Jawharī, Ibn Fāris, al-Rāghib, al-Miṣbāḥ.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حير:jawhari_sihah', 'حير', 'cc748d32be2b7b6f69964558d0', 'أي تحَيَّرَ في أمره، فهو حَيْرانُ', 'he was at a loss in his affair', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_54f2e05238360a85', '1268', 2, 'blk_sih_a0d581a149bc1b26', 0, NULL, 'Marker: «أي». Reading: being at a loss. Differs from the main reading (dazzled sight).', 'high', 'active');
