INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حير:ibn_manzur_lisan_arab', 'حير', 'cc748d32be2b7b6f69964558d0', 'حَارَ بَصَرُه يَحارُ حَيْرَةً وحَيْراً وحَيَراناً وتَحيَّر إِذا نَظَرَ إِلى الشَّيْءِ فَعَشيَ بَصَرُهُ', 'eyes dazzled on looking at a thing', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_dc2c1b6e221dbddc', '2182', 4, 'blk_lsn_88b679e2f0bc523b', 0, NULL, 'Marker: head gloss. Reading: dazzled sight.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حير:fayyumi_misbah_munir', 'حير', 'cc748d32be2b7b6f69964558d0', 'حَارَ فِي أَمْرِهِ يَحَارُ حَيَرًا مِنْ بَابِ تَعِبَ وَحَيْرَةً لَمْ يَدْرِ وَجْهَ الصَّوَابِ', 'did not know the right way', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_6a64249393a5fcd0', '777', NULL, 'blk_msb_dde2a5c81182846f', 0, NULL, 'Marker: head gloss. Reading: being at a loss. Differs from the main reading (dazzled sight).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حير:zabidi_taj_arus', 'حير', 'cc748d32be2b7b6f69964558d0', 'الحَيْرَة أَنْ يَنظُر الإِنسَانُ إِلى شَيْءٍ فيَغْشَاه ضَوْؤُه فيَصْرِفَ بصَرَه عَنهُ', 'looking at a thing, its light dazzles you, you look away', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_2f6e3e28d8d52c59', '116', 11, 'blk_taj_298eb99dee62607a', 0, NULL, 'Marker: «أصل» (al-Azharī via Tāj). Reading: dazzled sight.', 'medium', 'active');
