-- خبز
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:khalil_kitab_ayn', 'خبز', 'fd507065c66c2f817841a9750f', 'الخَبْزُ: الضرب باليد، والخَبْزُ: السوق الشديد', 'striking with the hand; hard driving', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_d15984e4abb6ce7c', '1319', NULL, 'blk_kay_e5b766e826894783', 0, NULL, 'Marker: head gloss. Reading: striking by hand. Primary: striking with the hand — 5 of 10 books (al-Khalīl blk_kay_e5b766e826894783; Ibn Durayd blk_jam_ec5822d177651a94; Ibn Fāris blk_mqy_a575899e3e83bf02; al-Qāmūs blk_qms_62f00616e08598a6; Tāj blk_taj_522a301ddc98622a). Other readings: bread, baking: al-Jawharī, al-Rāghib, Lisān, al-Miṣbāḥ, Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:ibn_durayd_jamharat_lugha', 'خبز', 'fd507065c66c2f817841a9750f', 'وَالْخبْز: ضرب الْبَعِير بِيَدِهِ الأَرْض فِي مَشْيه. وَبِه سمي الْخبز لضربهم إِيَّاه بِأَيْدِيهِم', 'a camel striking the ground; bread named from hand-beating', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_d2e44a386d7f289c', '251', NULL, 'blk_jam_ec5822d177651a94', 0, NULL, 'Marker: head gloss. Reading: striking by hand.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:jawhari_sihah', 'خبز', 'fd507065c66c2f817841a9750f', 'الذي يؤكل. والخَبْزُ بالفتح المصدرُ. وقد خَبَزْتُ الخُبْزَ وأخْبَزتُه', 'bread, what is eaten; baking it', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_c720b87e5be46693', '1733', 3, 'blk_sih_b48506be8f3f7020', 0, NULL, 'Marker: head gloss. Reading: bread. Differs from the main reading (striking with the hand).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:raghib_mufradat', 'خبز', 'fd507065c66c2f817841a9750f', 'الخُبْز معروف', 'bread, a known word', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_8577d4b5bcadd724', '273', 1, 'blk_mfr_64e888be7bfc5cd3', 0, NULL, 'Marker: opening definition. Reading: bread. Differs from the main reading (striking with the hand).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:ibn_manzur_lisan_arab', 'خبز', 'fd507065c66c2f817841a9750f', 'والخُبْزُ: الَّذِي يُؤْكَلُ. والخَبْزُ، بِالْفَتْحِ: الْمَصْدَرُ، خَبَزَه يَخْبِزه خَبْزاً واخْتَبَزَه: عَمِلَهُ', 'bread, what is eaten; to make it', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_5258674024b86828', '2927', 5, 'blk_lsn_3142765011c1206c', 0, NULL, 'Marker: head gloss. Reading: bread. Differs from the main reading (striking with the hand).', 'high', 'active');
