INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خبز:qamus_muhit', 'خبز', 'fd507065c66c2f817841a9750f', 'وبالفتح: ضَرْبُ البعيرِ بيَدِهِ الأرضَ، والسَّوْقُ الشديدُ، والضَّرْبُ', 'a camel striking the ground; hard driving; striking', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_225aee294d488c20', NULL, NULL, 'blk_qms_62f00616e08598a6', 0, NULL, 'Marker: Qāmūs gloss. Reading: striking.', 'high', 'active');
